const t = p.thickness;
const back = box(t, p.width, p.height);
const arm = box(p.reach, p.width, t);
const gusset = box(p.reach * 0.5, t, p.height * 0.5).translate(0, (p.width - t) / 2, 0);
const holes = [0.3, 0.75].map((f) => cylinder(t + 2, 3).rotate(0, 90, 0).translate(-1, p.width / 2, p.height * f));
return back.add(arm, gusset).subtract(holes);
